//! Production-DBC parity suite. `#[ignore]`d; gated on
//! `MANGOS_DBC_DIR` pointing at a directory of production `.dbc`
//! files (the dev bench: `~/azeroth-dev-fixtures/datadir/5875/dbc`).
//! Goldens in `dbc_oracle.rs` were generated by the independent
//! Python oracle `vmangos-rs/scripts/dbc_oracle_gen.py` (built on
//! `scripts/dbc.py`) — regenerate there, never from Rust output.
//!
//! Run: `MANGOS_DBC_DIR=... cargo test -p mangos-dbc -- --ignored`

use std::path::PathBuf;

use mangos_dbc::{DbcError, DbcFile, FieldFormat, formats::ALL_STORES, parse_format};
use sha2::{Digest, Sha256};

mod dbc_oracle;
use dbc_oracle::{FILES, STORES};

fn dbc_dir() -> PathBuf {
    std::env::var_os("MANGOS_DBC_DIR")
        .expect("MANGOS_DBC_DIR must be set for production DBC parity tests")
        .into()
}

use std::fmt::Write as _;

fn hex_of(bytes: &[u8]) -> String {
    bytes.iter().fold(String::new(), |mut out, b| {
        let _ = write!(out, "{b:02x}");
        out
    })
}

fn sha256_hex(data: &[u8]) -> String {
    hex_of(&Sha256::digest(data))
}

fn read_header_counts(bytes: &[u8]) -> (u32, u32) {
    let fc = u32::from_le_bytes(bytes[8..12].try_into().expect("header"));
    let rc = u32::from_le_bytes(bytes[4..8].try_into().expect("header"));
    (rc, fc)
}

#[test]
#[ignore = "requires MANGOS_DBC_DIR with production DBC fixtures"]
fn all_158_files_headers_and_sections() {
    let dir = dbc_dir();
    assert_eq!(FILES.len(), 158, "golden covers every production DBC");
    for golden in FILES {
        let bytes = std::fs::read(dir.join(golden.name)).expect("fixture file present");
        if golden.empty_file {
            assert!(bytes.is_empty(), "{} expected zero-byte", golden.name);
            assert_eq!(
                DbcFile::parse(&bytes, "n").unwrap_err(),
                DbcError::Truncated
            );
            continue;
        }
        let (_rc, fc) = read_header_counts(&bytes);
        let generic_fmt = "x".repeat(fc as usize);
        let dbc = DbcFile::parse(&bytes, &generic_fmt)
            .unwrap_or_else(|e| panic!("{}: parse failed: {e}", golden.name));
        assert_eq!(dbc.record_count(), golden.record_count, "{}", golden.name);
        assert_eq!(dbc.field_count(), golden.field_count, "{}", golden.name);
        assert_eq!(dbc.record_size(), golden.record_size, "{}", golden.name);
        assert_eq!(dbc.string_size(), golden.string_size, "{}", golden.name);
        assert_eq!(
            sha256_hex(dbc.records_bytes()),
            golden.records_sha256,
            "{} record section",
            golden.name
        );
        assert_eq!(
            sha256_hex(dbc.string_block()),
            golden.strings_sha256,
            "{} string block",
            golden.name
        );
    }
}

#[test]
#[ignore = "requires MANGOS_DBC_DIR with production DBC fixtures"]
fn all_46_stores_produced_values() {
    let dir = dbc_dir();
    assert_eq!(ALL_STORES.len(), 46);
    assert_eq!(STORES.len(), 46);
    for store in ALL_STORES {
        let golden = STORES
            .iter()
            .find(|g| g.file == store.file)
            .unwrap_or_else(|| panic!("golden missing for {}", store.file));
        let bytes = std::fs::read(dir.join(store.file)).expect("store file present");
        let dbc = DbcFile::parse(&bytes, store.fmt)
            .unwrap_or_else(|e| panic!("{}: parse failed: {e}", store.file));
        assert_eq!(
            store.fmt.len() as u32,
            dbc.field_count(),
            "{} strlen(fmt) == fieldCount (C++ loader invariant)",
            store.file
        );

        // Produced digest over raw field accessors in fmt order,
        // skipping x/d — mirrors AutoProduceData cell semantics and
        // the Python oracle's digest construction.
        let format = parse_format(store.fmt).expect("fmt parses");
        let mut hasher = Sha256::new();
        for id in 0..dbc.record_count() {
            let record = dbc.record(id).expect("row");
            for (x, field) in format.iter().enumerate() {
                match field {
                    FieldFormat::Float => {
                        hasher.update(b"f");
                        hasher.update(record.f32(x).expect("f32").to_le_bytes());
                    }
                    FieldFormat::Int | FieldFormat::Index => {
                        hasher.update(b"i");
                        hasher.update(record.u32(x).expect("u32").to_le_bytes());
                    }
                    FieldFormat::Byte => {
                        hasher.update(b"b");
                        hasher.update([record.u8(x).expect("u8")]);
                    }
                    FieldFormat::String => {
                        hasher.update(b"s");
                        hasher.update(record.string_bytes(x).expect("string"));
                        hasher.update([0u8]);
                    }
                    _ => {}
                }
            }
        }
        let digest = hex_of(&hasher.finalize());
        assert_eq!(
            digest, golden.produced_sha256,
            "{} produced values",
            store.file
        );

        // Index shape: row_count == max_index + 1 (or record count).
        let produced = dbc.produce(store.fmt).expect("produce");
        match golden.max_index {
            Some(max) => assert_eq!(produced.row_count(), max + 1, "{}", store.file),
            None => assert_eq!(produced.row_count(), dbc.record_count(), "{}", store.file),
        }
        assert_eq!(produced.len() as u32, dbc.record_count(), "{}", store.file);
    }
}
